WITH parsed AS (SELECT id, customer_id, created_at, coupon_codes, items, ship_to, SIZE(items) AS num_items, ARRAY_CONTAINS(MAP_KEYS(attributes), 'weight_kg') AS has_weight_kg, EXISTS(coupon_codes, c -> c LIKE 'W%') AS has_welcome_code, EXISTS(items, li -> li.price > 100) AS has_premium_item FROM carts) SELECT id, customer_id, created_at, coupon_codes, has_welcome_code, has_premium_item, LAG(num_items) OVER (PARTITION BY customer_id ORDER BY created_at ASC, id ASC) prev_num_items, LEAD(num_items) OVER (PARTITION BY customer_id ORDER BY created_at ASC, id ASC) next_num_items, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY created_at ASC, id ASC) event_seq FROM parsed;
